CREATE    VIEW [FO].[vwProductGroup]
AS 
SELECT 
	T1.[ITEMGROUPID] AS [GROUPID],
	T1.[NAME] AS [GROUPNAME],
	CASE
		WHEN T1.[ITEMGROUPID] IN ('A4', 'J1', 'M2') THEN 'Advertising Products'
		WHEN T1.[ITEMGROUPID] IN ('E2') THEN 'Awards'
		WHEN T1.[ITEMGROUPID] IN ('D1', 'D2', 'O2', 'A5') THEN 'DRS'
		WHEN T1.[ITEMGROUPID] IN ('E1', 'O1', 'P1', 'T1', 'T3', 'T4', 'T5', 'W1') THEN 'Knowledge & Competence'
		WHEN T1.[ITEMGROUPID] IN ('A1', 'F1', 'L1', 'M5', 'O6', 'Q1', 'Q2', 'R1', 'R3', 'S1', 'S2', 'S3', 'S4', 'U1') THEN 'Not Commercial'
		WHEN T1.[ITEMGROUPID] IN ('A3', 'B1', 'G1', 'M1', 'M3', 'O5') THEN 'Other Commercial Income'
		WHEN T1.[ITEMGROUPID] IN ('B2', 'B3', 'B4', 'C1', 'H1', 'I1') THEN 'Practitioner Products'
		WHEN T1.[ITEMGROUPID] = 'DM' THEN 'Data Migration'
		--WHEN T1.[ITEMGROUPID] IS NULL THEN 'Unknown'
		ELSE 'Not Defined' END AS 'Product Super Group',
	--T1.STANDARDITEMALLOCATEID AS [DEFAULTFORECASTALLOCATIONKEYID],
	--T1.TAXITEMGROUPIDSALES AS [DEFAULTSALESSALESTAXITEMGROUPCODE],
	--T1.TAXITEMGROUPIDPURCH AS [DEFAULTPURCHASESALESTAXITEMGROUPCODE],
	--T1.LOADTEMPLATEID AS [SHIPMENTPHYSICALLOADTEMPLATEID],
	--T2.FILTERREQUIRED AS [ISWAREHOUSEFILTERCODEREQUIRED],
	--T2.FILTERREQUIRED2_ AS [ISWAREHOUSEFILTERCODEREQUIRED2_],
	--T2.FILTERREQUIRED3_ AS [ISWAREHOUSEFILTERCODEREQUIRED3_],
	--T2.FILTERREQUIRED4_ AS [ISWAREHOUSEFILTERCODEREQUIRED4_],
	--T2.FILTERUSEDFORGROUP AS [ISFILTERCODEDETERMININGWAREHOUSEFILTERGROUP],
	--T2.FILTERUSEDFORGROUP2_ AS [ISFILTERCODEDETERMININGWAREHOUSEFILTERGROUP2_],
	--T2.FILTERUSEDFORGROUP3_ AS [ISFILTERCODEDETERMININGWAREHOUSEFILTERGROUP3_],
	--T2.FILTERUSEDFORGROUP4_ AS [ISFILTERCODEDETERMININGWAREHOUSEFILTERGROUP4_],
	T1.[PARTITION],
	--T1.[REVRECDEFAULTREVENUERECOGNITIONSCHEDULE],
	--T1.[REVRECEXCLUDEFROMCARVEOUT],
	--T1.[REVRECMEDIANPRICE],
	--T1.[REVRECMEDIANPRICEMAXIMUMTOLERANCE],
	--T1.[REVRECMEDIANPRICEMINIMUMTOLERANCE],
	--T1.[REVRECREVENUERECOGNITIONENABLED],
	--T1.[REVRECREVENUETYPE],
	--T2.FILTERREQUIRED5_ AS [ISWAREHOUSEFILTERCODEREQUIRED5_],
	--T2.FILTERREQUIRED6_ AS [ISWAREHOUSEFILTERCODEREQUIRED6_],
	--T2.FILTERREQUIRED7_ AS [ISWAREHOUSEFILTERCODEREQUIRED7_],
	--T2.FILTERREQUIRED8_ AS [ISWAREHOUSEFILTERCODEREQUIRED8_],
	--T2.FILTERREQUIRED9_ AS [ISWAREHOUSEFILTERCODEREQUIRED9_],
	--T2.FILTERREQUIRED10_ AS [ISWAREHOUSEFILTERCODEREQUIRED10_],
	--T2.FILTERUSEDFORGROUP5_ AS [ISFILTERCODEDETERMININGWAREHOUSEFILTERGROUP5_],
	--T2.FILTERUSEDFORGROUP6_ AS [ISFILTERCODEDETERMININGWAREHOUSEFILTERGROUP6_],
	--T2.FILTERUSEDFORGROUP7_ AS [ISFILTERCODEDETERMININGWAREHOUSEFILTERGROUP7_],
	--T2.FILTERUSEDFORGROUP8_ AS [ISFILTERCODEDETERMININGWAREHOUSEFILTERGROUP8_],
	--T2.FILTERUSEDFORGROUP9_ AS [ISFILTERCODEDETERMININGWAREHOUSEFILTERGROUP9_],
	--T2.FILTERUSEDFORGROUP10_ AS [ISFILTERCODEDETERMININGWAREHOUSEFILTERGROUP10_],
	T1.[DATAAREAID],
	T1.[DataLakeModified_DateTime]
FROM [synapse_fo].[INVENTITEMGROUP] T1
	LEFT OUTER JOIN [synapse_fo].[WHSFILTERPARM] T2 
	ON (
				(
					(T1.ITEMGROUPID = T2.ITEMGROUPID)
					AND (T1.DATAAREAID = T2.DATAAREAID)
					)
			AND (T1.PARTITION = T2.PARTITION)
		
		)
WHERE  T1.[DATAAREAID] = 'rcs'
